# zip_lists :: ([[1, 2], [3, 4], [5, 6]])
def zip_lists(rows):
    if not rows:
        return []
    return [list(c) for c in zip(*rows)]

if __name__ == '__main__':
    print(zip_lists(([[1, 2], [3, 4], [5, 6]])))

